        } ?: "Activo — esperando señal"
        active -> "Activo — arranca con el motor"
        else -> "Inactivo"
    }
    Text(
        text,
        style = MaterialTheme.typography.labelSmall,
        color = if (active && isRunning) LimeActive else CyanGlow
    )
}

